#!/usr/bin/env python3
import itertools, sys, json

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]

def find_partition():
    triples = []
    Lset = set(L)
    for a,b in itertools.combinations(L,2):
        c = a + b
        if c in Lset and c != a and c != b:
            triples.append((a,b,c))
    triples_by_num = {num: [] for num in L}
    for t in triples:
        a,b,c = t
        triples_by_num[a].append(t)
        triples_by_num[b].append(t)
        triples_by_num[c].append(t)
    solution = []
    def backtrack(remaining):
        if not remaining:
            return solution.copy()
        num = min(remaining, key=lambda x: len([t for t in triples_by_num[x] if all(v in remaining for v in t)]))
        for t in triples_by_num[num]:
            a,b,c = t
            if a in remaining and b in remaining and c in remaining:
                solution.append(t)
                new_remaining = remaining - {a,b,c}
                res = backtrack(new_remaining)
                if res is not None:
                    return res
                solution.pop()
        return None
    return backtrack(set(L))

def main():
    partition = find_partition()
    if partition:
        print(\"Partition found:\")
        for triple in partition:
            print(triple)
        witness = {\"polarity\": \"positive\", \"evidence\": {\"path\": \"execution://witness\"}, \"data\": {\"partition\": partition}}
        print(\"WITNESS:\", json.dumps(witness))
    else:
        print(\"No valid partition exists.\")
        witness = {\"polarity\": \"negative\", \"evidence\": {\"path\": \"execution://witness\"}, \"basis\": \"proof\", \"argument\": \"Exhaustive search did not find a valid partition.\"}
        print(\"WITNESS:\", json.dumps(witness))

if __name__ == \"__main__\":
    main()
